const stages={
 'Maíz':{title:'El campo se llena de maíz',text:'Esta es la primera campaña del ejemplo. Antes de sembrar, confirma que el riego pueda sostenerla.',color:'#e9c85a'},
 'leguminosa':{title:'Ahora cambia el cultivo',text:'Después de la cosecha, entra una leguminosa. Rotar significa cambiar la familia del cultivo en este lote; la especie concreta debe elegirse con un técnico.',color:'#9fd480'},
 'Leguminosa':{title:'Comienza con una leguminosa',text:'Explora esta campaña como una alternativa. Su adaptación depende de la especie, el suelo y el agua reales.',color:'#9fd480'},
 'Yuca':{title:'Una campaña de yuca',text:'Este ejemplo ocupa el lote durante más tiempo. Comprueba suelo, agua y mercado antes de comprometer el terreno.',color:'#74bc9a'},
 'descanso':{title:'Una pausa para revisar el terreno',text:'Se termina la campaña y se revisa el suelo. Descansar no recupera el suelo por sí solo: acuerda cobertura y manejo con tu técnico.',color:'#cbb18a'}};
function plant(x,y,i,kind){const rest=kind==='descanso',corn=kind==='Maíz';return '<g class="rotation-plant" style="--delay:'+i*18+'ms" transform="translate('+x+' '+y+')"><ellipse cy="7" rx="15" ry="6" fill="#0a352b30"/>'+(rest?'<path d="M-12 0l24 4m-20 2 15-9" stroke="#d4bd83" stroke-width="3"/>':'<g class="rotation-stem"><path d="M0 0v-'+(corn?65:36)+'" stroke="#386b43" stroke-width="4"/><path d="M0-15Q-30-42-23-45Q0-43 0-15M0-25Q29-55 25-51Q3-48 0-25" fill="#82b653"/>'+(corn?'<ellipse cx="4" cy="-37" rx="6" ry="14" fill="#f1ca59"/><path d="M0-65l-8-10m8 10 8-10" stroke="#e8d492" stroke-width="3"/>':'<ellipse cx="-10" cy="-36" rx="12" ry="7" fill="#9fd480"/><ellipse cx="10" cy="-42" rx="12" ry="7" fill="#609f52"/>')+'</g>')+'</g>';}
export function mountRotationStage(host){let sequence=['Maíz','leguminosa','descanso'],step=0;
host.innerHTML='<section class="rotation-theatre"><div class="rotation-heading"><small>UN CAMPO. DISTINTAS ETAPAS.</small><h2>Mira cómo cambia<br>tu próxima campaña.</h2><p>Elige un recorrido y toca cada etapa. Los árboles permanecen; el lote anual cambia.</p><label>Recorrido ilustrativo<select id="rotation-choice"><option>Maíz → leguminosa → descanso</option><option>Leguminosa → descanso</option><option>Yuca → descanso</option></select></label></div><div class="rotation-scene" id="rotation-scene"></div><div class="rotation-story" aria-live="polite"></div><nav class="rotation-timeline" aria-label="Etapas de la rotación"></nav><div class="rotation-actions"><button type="button" id="rotation-prev">← Anterior</button><button type="button" id="rotation-next">Siguiente etapa →</button></div><p class="rotation-note">Ilustración educativa de un lote anual separado, no de tu polígono real. No representa rendimientos ni un calendario validado.</p></section>';
function draw(){const kind=sequence[step],s=stages[kind];host.querySelector('#rotation-scene').innerHTML='<svg viewBox="0 0 800 390" role="img" aria-label="Lote anual en etapa de '+kind+', junto a frutales que se conservan"><ellipse cx="400" cy="344" rx="330" ry="29" fill="#06251e50"/><circle cx="681" cy="65" r="32" fill="#f1cd77"/><path d="M70 180 390 55 735 186 415 335Z" fill="#b5c982"/><path d="M70 180v33l345 155v-33Z" fill="#98704c"/><path d="M415 335v33l320-149v-33Z" fill="#70583e"/><path d="M105 185 330 95 540 183 315 280Z" fill="#97764d"/>'+[0,1,2,3].map(r=>'<path d="M'+(118+r*45)+' '+(190+r*19)+'l220-88" stroke="#c9ac76" stroke-width="4"/>').join('')+Array.from({length:20},(_,i)=>plant(145+(i%5)*41+Math.floor(i/5)*35,184-(i%5)*16+Math.floor(i/5)*22,i,kind)).join('')+'<path d="M365 90 605 190 420 287" fill="none" stroke="#7fc9c1" stroke-width="12"/>'+[0,1,2].map(i=>'<g transform="translate('+(528+i*57)+' '+(169+i*23)+')"><path d="M0 0v-35" stroke="#745438" stroke-width="7"/><circle cy="-49" r="30" fill="#367a4a"/><circle cx="-13" cy="-57" r="20" fill="#69a354"/><circle cx="9" cy="-37" r="5" fill="#edbf64"/></g>').join('')+'<text x="510" y="300" fill="#143e30" font-size="17" font-weight="700">Frutales: se conservan</text></svg>';
host.querySelector('.rotation-story').innerHTML='<small>ETAPA '+(step+1)+' DE '+sequence.length+'</small><h3>'+s.title+'</h3><p>'+s.text+'</p>';
host.querySelector('.rotation-timeline').innerHTML=sequence.map((v,i)=>'<button type="button" data-step="'+i+'" '+(i===step?'aria-current="step"':'')+'><span>'+(i+1)+'</span>'+v+'</button>').join('');host.querySelectorAll('[data-step]').forEach(el=>el.onclick=()=>{step=Number(el.dataset.step);draw()});host.querySelector('#rotation-prev').disabled=step===0;host.querySelector('#rotation-next').textContent=step===sequence.length-1?'Volver al inicio ↺':'Siguiente etapa →';}
host.querySelector('#rotation-choice').onchange=e=>{sequence=e.target.value.split(' → ');step=0;draw()};host.querySelector('#rotation-prev').onclick=()=>{step=Math.max(0,step-1);draw()};host.querySelector('#rotation-next').onclick=()=>{step=(step+1)%sequence.length;draw()};draw();}
